async function importMusicXml(file){if(!file)return;const previous=state;try{if(state.notes.length&&!confirm('Import this MusicXML file and replace the current score?'))return;const imported=parseMusicXmlComplete(await readMusicXml(file));state=previous;snap();state=imported;clearSelection();render();toast(`${state.notes.length} notes and rests imported from ${/\.mxl$/i.test(file.name)?'the MXL file':'Finale'}.`)}catch(error){state=previous;console.error(error);render();toast(error.message||'MusicXML import failed.')}}
